import {api} from './auth.js';
const decode=s=>Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));
const encode=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
export const passkeySupported=()=>isSecureContext&&!!window.PublicKeyCredential&&!!navigator.credentials;
function options(o,registration){const p={...o,challenge:decode(o.challenge)};if(registration)p.user={...o.user,id:decode(o.user.id)};for(const field of ['excludeCredentials','allowCredentials'])if(o[field])p[field]=o[field].map(c=>({...c,id:decode(c.id)}));return p;}
function json(c){const r=c.response,out={id:c.id,rawId:encode(c.rawId),type:c.type,clientExtensionResults:c.getClientExtensionResults(),response:{clientDataJSON:encode(r.clientDataJSON)}};if(r.attestationObject){out.response.attestationObject=encode(r.attestationObject);out.response.transports=r.getTransports?.()||[];}else{out.response.authenticatorData=encode(r.authenticatorData);out.response.signature=encode(r.signature);out.response.userHandle=r.userHandle?encode(r.userHandle):null;}return out;}
function message(e){return e.name==='NotAllowedError'?'Подтверждение отменено или недоступно. Можно войти по паролю.':e.name==='InvalidStateError'?'На этом устройстве ключ уже добавлен.':e.message||'Не удалось использовать ключ доступа.';}
export async function loginWithPasskey(){if(!passkeySupported())throw Error('Этот браузер не поддерживает ключи доступа.');const {options:o,challengeId}=await api('/api/passkeys/login-options',{method:'POST',body:'{}'});try{const c=await navigator.credentials.get({publicKey:options(o,false)});if(!c)throw Error('Вход не подтверждён.');return await api('/api/passkeys/login-verify',{method:'POST',body:JSON.stringify({challengeId,response:json(c)})});}catch(e){throw Error(message(e));}}
export async function passkeySettings(){const modal=document.getElementById('modal');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function draw(){const {keys}=await api('/api/passkeys/list');modal.innerHTML=`<div class="modal-header"><h2>Вход по отпечатку</h2><button data-close aria-label="Закрыть">×</button></div><div class="modal-body"><p>Подключите ключ доступа на этом устройстве. Телефон предложит отпечаток, лицо или PIN.</p><form id="passkey-register"><label class="field">Название устройства<input name="name" value="Мой телефон" maxlength="100" required></label><label class="field">Текущий пароль<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><button class="primary" ${passkeySupported()?'':'disabled'}>Подключить вход по отпечатку</button></form><h3 style="margin-top:24px">Ваши ключи доступа</h3>${keys.map(k=>`<div class="fin-line"><span>${esc(k.name)}</span><button data-remove-key="${esc(k.id)}">Удалить</button></div>`).join('')||'<p>Пока нет подключённых ключей.</p>'}<p class="error" role="alert"></p><p id="passkey-success" role="status"></p></div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;const f=new FormData(e.target);try{const {options:o,challengeId}=await api('/api/passkeys/register-options',{method:'POST',body:JSON.stringify({password:f.get('password')})});e.target.elements.password.value='';const c=await navigator.credentials.create({publicKey:options(o,true)});if(!c)throw Error('Создание ключа отменено.');await api('/api/passkeys/register-verify',{method:'POST',body:JSON.stringify({challengeId,response:json(c),name:f.get('name')})});await draw();modal.querySelector('#passkey-success').textContent='Ключ добавлен. При следующем входе нажмите «Войти по отпечатку».';}catch(err){modal.querySelector('.error').textContent=message(err);}finally{b.disabled=false;}};modal.querySelectorAll('[data-remove-key]').forEach(b=>b.onclick=()=>{modal.querySelector('#passkey-register').hidden=true;modal.querySelector('#passkey-success').innerHTML=`<form id="passkey-remove"><label class="field">Пароль для удаления ключа<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><button class="primary">Удалить ключ</button></form>`;modal.querySelector('#passkey-remove').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/passkeys/remove',{method:'POST',body:JSON.stringify({id:b.dataset.removeKey,password:new FormData(e.target).get('password')})});await draw();}catch(err){modal.querySelector('.error').textContent=message(err);button.disabled=false;}};});}await draw();modal.showModal();}
